<script setup lang="ts">
import { computed } from 'vue'
import type { OrderDetail } from '../../api/workorder'
import ProtectedImage from '../attachment/ProtectedImage.vue'
const roundTime = (value: string | null) => value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : '—'
const props = defineProps<{ detail: OrderDetail }>()
const current = computed(() => props.detail.rounds.find(r => r.round === props.detail.round) ?? props.detail.rounds.at(-1))
const previous = computed(() => props.detail.rounds.filter(r => r.id !== current.value?.id).reverse())
</script>
<template><section><p v-if="detail.historyScope === 'ASSIGNMENT_ONLY'" class="notice">本人分派历史只读：展示当时可见原报修材料及本人的分派、拒单／改派记录。</p><h2>原报修材料</h2><dl class="detail-grid"><dt>当次位置</dt><dd>{{ detail.requestMaterial.locationNameSnapshot ?? '旧文字位置' }}</dd><dt>用户名称／类别</dt><dd>{{ detail.requestMaterial.equipmentName }} · {{ detail.requestMaterial.equipmentCategory ?? '未填写' }}</dd><dt>原文地址</dt><dd>{{ detail.requestMaterial.addressText }}</dd><dt>原文描述</dt><dd class="pre-wrap">{{ detail.requestMaterial.description }}</dd><dt>联系快照</dt><dd>{{ detail.requestMaterial.contactName }} · {{ detail.requestMaterial.contactPhone }}</dd></dl><ProtectedImage v-for="photo in detail.requestMaterial.attachments" :key="photo.id" :attachment="photo" /><h2>分派记录</h2><ol><li v-for="a in detail.assignments" :key="a.id">第{{ a.assignmentNo }}次 · {{ a.technician.name }} · {{ { PENDING: '待接单', ACCEPTED: '已接单', REFUSED: '已拒单', REPLACED: '接单前已改派' }[a.outcome] }}<p>{{ a.reason }} {{ new Date(a.assignedAt).toLocaleString('zh-CN') }}</p></li></ol><template v-if="detail.historyScope === 'FULL'"><h2>本轮维修与验收</h2><p v-if="!current" class="muted">尚未接单，未产生维修轮次。</p><section v-if="current" class="round"><h3>第{{ current.round }}轮 · {{ current.technician.name }}</h3><p>开始：{{ roundTime(current.startedAt) }} · 提交：{{ roundTime(current.submittedAt) }}</p><ul><li v-for="p in current.progress" :key="p.id">{{ p.content }} · {{ new Date(p.recordedAt).toLocaleString('zh-CN') }}</li></ul><p class="pre-wrap">{{ current.result ?? '本轮尚未提交结果' }}</p><ProtectedImage v-for="photo in current.attachments" :key="photo.id" :attachment="photo" /><p v-if="current.acceptance">{{ current.acceptance.passed ? '验收通过' : '验收不通过' }} · {{ current.acceptance.reporter.name }} · {{ current.acceptance.reason }} · 验收：{{ roundTime(current.acceptance.acceptedAt) }}</p></section><details v-if="previous.length"><summary>展开以前{{ previous.length }}轮维修与验收</summary><section v-for="r in previous" :key="r.id" class="round"><h3>第{{ r.round }}轮 · {{ r.technician.name }}</h3><p>开始：{{ roundTime(r.startedAt) }} · 提交：{{ roundTime(r.submittedAt) }}</p><ul><li v-for="p in r.progress" :key="p.id">{{ p.content }} · {{ new Date(p.recordedAt).toLocaleString('zh-CN') }}</li></ul><p class="pre-wrap">{{ r.result ?? '本轮尚未提交结果' }}</p><ProtectedImage v-for="photo in r.attachments" :key="photo.id" :attachment="photo" /><p v-if="r.acceptance">{{ r.acceptance.passed ? '验收通过' : '验收不通过' }} · {{ r.acceptance.reporter.name }} · {{ r.acceptance.reason }} · 验收：{{ roundTime(r.acceptance.acceptedAt) }}</p></section></details></template><h2>有权查看的操作历史</h2><ul><li v-for="event in detail.events" :key="event.id">{{ event.actor.name }} · {{ event.type }} · {{ event.reason }} · {{ new Date(event.occurredAt).toLocaleString('zh-CN') }}</li></ul><p v-if="!detail.events.length" class="muted">暂无可见事件。</p></section></template>
<style scoped>.round { border-top: 1px solid #dce6ea; padding: 16px 0; }dd { overflow-wrap: anywhere; }.pre-wrap { white-space: pre-wrap; }</style>
